import React, { useState, useEffect } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ onSelectConversation, conversations, selectedConversation }) => {
  const [searchInput, setSearchInput] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [user, setUser] = useState(null);

  useEffect(() => {
    const loggedUser = JSON.parse(localStorage.getItem("user"));
    setUser(loggedUser);
    console.log("Logged-in user from localStorage:", loggedUser);
  }, []);

  const handleSearch = async () => {
    if (!searchInput.trim()) return;

    try {
      console.log("🔍 Searching by username with keywords:", searchInput);
      const response = await axios.get(
        `http://localhost:5000/api/profile/search?username=${searchInput}`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );

      const users = response.data;
      console.log("🔎 # of users found:", users.length);
      setSearchResults(users);
    } catch (err) {
      console.error("❌ Error searching users:", err);
    }
  };

  const handleUserClick = async (recipientId) => {
    try {
      setSelectedUserId(recipientId);

      const res = await axios.post(
        "http://localhost:5000/api/conversations",
        { senderId: user.userId, receiverId: recipientId },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );

      console.log("🧡 Conversation created or found:", res.data);
      onSelectConversation(res.data);
    } catch (err) {
      console.error("❌ Error starting conversation:", err);
    }
  };

  return (
    <div className="chat-sidebar">
      <h4>Messages</h4>

      <input
        type="text"
        value={searchInput}
        placeholder="Search users..."
        onChange={(e) => setSearchInput(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>

      <div className="search-results">
        {searchResults.map((usr) => (
          <div
            key={usr._id}
            className={`search-result ${selectedUserId === usr._id ? "selected" : ""}`}
            onClick={() => handleUserClick(usr._id)}
          >
            {usr.username}
          </div>
        ))}
      </div>

      <div className="conversation-list">
        {conversations && conversations.length > 0 ? (
          conversations.map((conv) => {
            const otherUser = conv.members.find((m) => m !== user?.userId);
            return (
              <div
                key={conv._id}
                className={`conversation-item ${selectedConversation?._id === conv._id ? "selected" : ""}`}
                onClick={() => onSelectConversation(conv)}
              >
                {otherUser}
              </div>
            );
          })
        ) : (
          <em>No conversations found.</em>
        )}
      </div>
    </div>
  );
};

export default ChatSidebar;
